import type { PrefabPlacement, TerrainPreset, TerrainSettings } from "../wizard/types";

/**
 * Procedural terrain preview, mirroring `engine/rust_studio_engine/procedural.py`.
 * Preview grids are coarse (257² by default) and uploaded as DataTextures; the
 * authoritative full-resolution layers are generated by the engine on export.
 */

const PRESETS: Record<TerrainPreset, { frequency: number; mountain: number; sea: number; detail: number }> = {
  islands: { frequency: 1.9, mountain: 0.9, sea: 0.42, detail: 0.55 },
  mountains: { frequency: 2.6, mountain: 1.8, sea: 0.18, detail: 0.7 },
  valley: { frequency: 1.3, mountain: 0.7, sea: 0.24, detail: 0.4 },
  flat: { frequency: 0.8, mountain: 0.08, sea: 0, detail: 0.1 },
  archipelago: { frequency: 3.4, mountain: 0.6, sea: 0.52, detail: 0.6 },
};

export interface TerrainPreview {
  resolution: number;
  heights: Float32Array;
  splat: Uint8Array;
  biome: Uint8Array;
  alpha: Uint8Array;
  topology: Uint32Array;
  minHeight: number;
  maxHeight: number;
}

function hash2(x: number, y: number, seed: number): number {
  let value = (x * 374761393 + y * 668265263 + seed * 1442695041) | 0;
  value = Math.imul(value ^ (value >>> 13), 1274126177);
  return ((value ^ (value >>> 16)) >>> 0) / 0xffffffff;
}

function smooth(t: number): number {
  return t * t * (3 - 2 * t);
}

function valueNoise(x: number, y: number, seed: number): number {
  const x0 = Math.floor(x);
  const y0 = Math.floor(y);
  const fx = smooth(x - x0);
  const fy = smooth(y - y0);
  const n00 = hash2(x0, y0, seed);
  const n10 = hash2(x0 + 1, y0, seed);
  const n01 = hash2(x0, y0 + 1, seed);
  const n11 = hash2(x0 + 1, y0 + 1, seed);
  const top = n00 + (n10 - n00) * fx;
  const bottom = n01 + (n11 - n01) * fx;
  return top + (bottom - top) * fy;
}

function fbm(x: number, y: number, seed: number, octaves = 5): number {
  let amplitude = 1;
  let frequency = 1;
  let total = 0;
  let norm = 0;
  for (let octave = 0; octave < octaves; octave += 1) {
    total += valueNoise(x * frequency, y * frequency, seed + octave * 1013) * amplitude;
    norm += amplitude;
    amplitude *= 0.5;
    frequency *= 2;
  }
  return total / norm;
}

export function generateTerrainPreview(settings: TerrainSettings, resolution = 257): TerrainPreview {
  const preset = PRESETS[settings.preset] ?? PRESETS.islands;
  const heights = new Float32Array(resolution * resolution);
  const splat = new Uint8Array(resolution * resolution * 8);
  const biome = new Uint8Array(resolution * resolution * 4);
  const alpha = new Uint8Array(resolution * resolution);
  const topology = new Uint32Array(resolution * resolution);
  const weights = settings.biomeWeights;
  const weightSum = weights.reduce((sum, value) => sum + value, 0) || 1;

  let minHeight = Number.POSITIVE_INFINITY;
  let maxHeight = Number.NEGATIVE_INFINITY;

  for (let y = 0; y < resolution; y += 1) {
    for (let x = 0; x < resolution; x += 1) {
      const u = x / (resolution - 1);
      const v = y / (resolution - 1);
      const radial = Math.hypot(u - 0.5, v - 0.5) * 2;
      const island = Math.max(0, 1 - radial * radial * (1 + preset.sea));

      const base = fbm(u * preset.frequency * 2.2, v * preset.frequency * 2.2, settings.seed);
      const ridgeSource = fbm(
        u * preset.frequency * 3.4 + 11.3,
        v * preset.frequency * 3.4 - 4.7,
        settings.seed + 91,
        4,
      );
      const ridges = 1 - Math.abs(ridgeSource * 2 - 1);

      let height = (base - 0.5) * 240 * (0.6 + settings.detail);
      height += ridges * ridges * 260 * preset.mountain * settings.mountainScale;
      height *= 0.35 + island * 0.9;
      height -= preset.sea * 120;

      const index = y * resolution + x;
      heights[index] = height;
      minHeight = Math.min(minHeight, height);
      maxHeight = Math.max(maxHeight, height);

      const slope = Math.abs(
        fbm(u * preset.frequency * 6, v * preset.frequency * 6, settings.seed + 7, 3) - 0.5,
      );

      let mixes: [number, number, number, number, number, number, number, number];
      if (height < settings.waterLevel + 4) mixes = [200, 20, 35, 0, 0, 0, 0, 0];
      else if (height > 220) mixes = [0, 120, 0, 40, 0, 0, 55, 0];
      else if (height > 120 || slope > 0.32) mixes = [25, 25, 0, 85, 20, 0, 100, 0];
      else mixes = [45, 0, 0, 0, 120, 85, 0, 5];

      for (let channel = 0; channel < 8; channel += 1) {
        splat[index * 8 + channel] = mixes[channel];
      }

      let dominant = 0;
      if (height > 160) dominant = 2;
      else if (height < settings.waterLevel + 20) dominant = 1;
      for (let channel = 0; channel < 4; channel += 1) {
        biome[index * 4 + channel] = Math.min(
          255,
          Math.round((255 * weights[channel]) / weightSum) + (channel === dominant ? 40 : 0),
        );
      }

      alpha[index] = 255;
      topology[index] = 0;
    }
  }

  return {
    resolution,
    heights,
    splat,
    biome,
    alpha,
    topology,
    minHeight: Number.isFinite(minHeight) ? minHeight : 0,
    maxHeight: Number.isFinite(maxHeight) ? maxHeight : 1,
  };
}

/**
 * Flatten preview heights under monument pads with the same inner radius and
 * smooth falloff used by the exporter. Also stamps the editor topology flags so
 * Studio Mode can show the no-build and foliage-cleared footprints.
 */
export function applyPlacementPads(
  preview: TerrainPreview,
  placements: PrefabPlacement[],
  sizeMetres: number,
): void {
  if (!placements.length) return;
  const resolution = preview.resolution;
  const texel = sizeMetres / Math.max(1, resolution - 1);
  const half = sizeMetres / 2;
  const NO_BUILD = 1 << 24;
  const MONUMENT_PAD = 1 << 25;
  const FOLIAGE_CLEARED = 1 << 26;

  for (const placement of placements) {
    if (placement.flatten === false) continue;
    const radius = Math.max(0, placement.flattenRadius);
    if (radius <= 0) continue;
    const falloff = Math.max(0, placement.flattenFalloff);
    const outer = radius + falloff;
    const centreX = placement.position.x;
    const centreZ = placement.position.z;
    const centreGridX = Math.round((centreX + half) / texel);
    const centreGridZ = Math.round((centreZ + half) / texel);
    const radiusTexels = Math.ceil(outer / texel);

    let total = 0;
    let count = 0;
    const averageRadius = Math.max(1, Math.ceil(radius / texel));
    for (let iz = centreGridZ - averageRadius; iz <= centreGridZ + averageRadius; iz += 1) {
      if (iz < 0 || iz >= resolution) continue;
      for (let ix = centreGridX - averageRadius; ix <= centreGridX + averageRadius; ix += 1) {
        if (ix < 0 || ix >= resolution) continue;
        total += preview.heights[iz * resolution + ix];
        count += 1;
      }
    }
    const target = count ? total / count : 0;

    for (let iz = centreGridZ - radiusTexels; iz <= centreGridZ + radiusTexels; iz += 1) {
      if (iz < 0 || iz >= resolution) continue;
      const worldZ = (iz - (resolution - 1) / 2) * texel;
      for (let ix = centreGridX - radiusTexels; ix <= centreGridX + radiusTexels; ix += 1) {
        if (ix < 0 || ix >= resolution) continue;
        const worldX = (ix - (resolution - 1) / 2) * texel;
        const distance = Math.hypot(worldX - centreX, worldZ - centreZ);
        if (distance > outer) continue;
        const weight =
          distance <= radius
            ? 1
            : 1 - smoothstep((distance - radius) / Math.max(1e-6, falloff));
        const index = iz * resolution + ix;
        preview.heights[index] += (target - preview.heights[index]) * weight;
      }
    }

    for (let iz = centreGridZ - radiusTexels; iz <= centreGridZ + radiusTexels; iz += 1) {
      if (iz < 0 || iz >= resolution) continue;
      const worldZ = (iz - (resolution - 1) / 2) * texel;
      for (let ix = centreGridX - radiusTexels; ix <= centreGridX + radiusTexels; ix += 1) {
        if (ix < 0 || ix >= resolution) continue;
        const worldX = (ix - (resolution - 1) / 2) * texel;
        const distance = Math.hypot(worldX - centreX, worldZ - centreZ);
        if (distance > outer) continue;
        const index = iz * resolution + ix;
        if (distance <= radius * 1.15) {
          preview.topology[index] |= FOLIAGE_CLEARED | MONUMENT_PAD;
        }
        if (distance <= radius) preview.topology[index] |= NO_BUILD;
      }
    }
  }
}

function smoothstep(value: number): number {
  const t = Math.min(1, Math.max(0, value));
  return t * t * (3 - 2 * t);
}

export function worldToGrid(worldX: number, worldZ: number, sizeMetres: number, resolution: number): [number, number] {
  const gx = ((worldX + sizeMetres / 2) / sizeMetres) * (resolution - 1);
  const gz = ((worldZ + sizeMetres / 2) / sizeMetres) * (resolution - 1);
  return [gx, gz];
}

export function samplePreviewHeight(
  preview: TerrainPreview,
  worldX: number,
  worldZ: number,
  sizeMetres: number,
): number {
  const [gx, gz] = worldToGrid(worldX, worldZ, sizeMetres, preview.resolution);
  const x0 = Math.max(0, Math.min(preview.resolution - 1, Math.floor(gx)));
  const z0 = Math.max(0, Math.min(preview.resolution - 1, Math.floor(gz)));
  const x1 = Math.min(preview.resolution - 1, x0 + 1);
  const z1 = Math.min(preview.resolution - 1, z0 + 1);
  const tx = Math.max(0, Math.min(1, gx - x0));
  const tz = Math.max(0, Math.min(1, gz - z0));
  const h00 = preview.heights[z0 * preview.resolution + x0];
  const h10 = preview.heights[z0 * preview.resolution + x1];
  const h01 = preview.heights[z1 * preview.resolution + x0];
  const h11 = preview.heights[z1 * preview.resolution + x1];
  const top = h00 + (h10 - h00) * tx;
  const bottom = h01 + (h11 - h01) * tx;
  return top + (bottom - top) * tz;
}

/** Apply one brush stamp to the preview heightfield. Returns true if modified. */
export function applyBrushToPreview(
  preview: TerrainPreview,
  settings: TerrainSettings,
  worldX: number,
  worldZ: number,
): boolean {
  const brush = settings.brush;
  const resolution = preview.resolution;
  const texel = settings.sizeMetres / (resolution - 1);
  const [centreX, centreZ] = worldToGrid(worldX, worldZ, settings.sizeMetres, resolution);
  const radius = Math.max(1, Math.ceil(brush.radius / texel));
  const x0 = Math.max(0, Math.floor(centreX - radius));
  const x1 = Math.min(resolution - 1, Math.ceil(centreX + radius));
  const z0 = Math.max(0, Math.floor(centreZ - radius));
  const z1 = Math.min(resolution - 1, Math.ceil(centreZ + radius));
  let modified = false;

  for (let z = z0; z <= z1; z += 1) {
    for (let x = x0; x <= x1; x += 1) {
      const worldGridX = (x / (resolution - 1)) * settings.sizeMetres - settings.sizeMetres / 2;
      const worldGridZ = (z / (resolution - 1)) * settings.sizeMetres - settings.sizeMetres / 2;
      const distance = Math.hypot(worldGridX - worldX, worldGridZ - worldZ);
      if (distance > brush.radius) continue;
      const weight = Math.pow(1 - distance / brush.radius, Math.max(0.5, brush.falloff));
      const index = z * resolution + x;

      switch (brush.mode) {
        case "raise":
          preview.heights[index] += brush.strength * weight;
          modified = true;
          break;
        case "lower":
          preview.heights[index] -= brush.strength * weight;
          modified = true;
          break;
        case "smooth": {
          const neighbours = [
            preview.heights[index - 1] ?? preview.heights[index],
            preview.heights[index + 1] ?? preview.heights[index],
            preview.heights[index - resolution] ?? preview.heights[index],
            preview.heights[index + resolution] ?? preview.heights[index],
          ];
          const average = neighbours.reduce((sum, value) => sum + value, 0) / neighbours.length;
          preview.heights[index] += (average - preview.heights[index]) * Math.min(1, weight);
          modified = true;
          break;
        }
        case "flatten": {
          const target = preview.heights[index];
          preview.heights[index] += (target - preview.heights[index]) * Math.min(1, weight);
          break;
        }
        case "splat": {
          const channel = SPLAT_INDEX[brush.splatChannel] ?? 4;
          const offset = index * 8;
          let total = 0;
          for (let c = 0; c < 8; c += 1) total += preview.splat[offset + c];
          const current = preview.splat[offset + channel];
          preview.splat[offset + channel] = Math.min(255, current + (255 - current) * weight);
          const newTotal = total + preview.splat[offset + channel] - current || 1;
          for (let c = 0; c < 8; c += 1) {
            preview.splat[offset + c] = Math.round((preview.splat[offset + c] * 255) / newTotal);
          }
          modified = true;
          break;
        }
        case "alpha":
          preview.alpha[index] = 0;
          modified = true;
          break;
        case "topology": {
          let mask = 0;
          for (const flag of brush.topologyFlags) mask |= TOPOLOGY_BITS[flag] ?? 0;
          preview.topology[index] |= mask;
          modified = true;
          break;
        }
      }
    }
  }

  if (modified && (brush.mode === "raise" || brush.mode === "lower" || brush.mode === "smooth")) {
    preview.minHeight = Number.POSITIVE_INFINITY;
    preview.maxHeight = Number.NEGATIVE_INFINITY;
    for (let i = 0; i < preview.heights.length; i += 1) {
      preview.minHeight = Math.min(preview.minHeight, preview.heights[i]);
      preview.maxHeight = Math.max(preview.maxHeight, preview.heights[i]);
    }
  }
  return modified;
}

export const SPLAT_INDEX: Record<string, number> = {
  dirt: 0,
  snow: 1,
  sand: 2,
  rock: 3,
  grass: 4,
  forest: 5,
  stones: 6,
  gravel: 7,
};

/** Editor overlay bits, matching EDITOR_TOPOLOGY_FLAGS in the Python engine. */
export const TOPOLOGY_BITS: Record<string, number> = {
  no_build: 1 << 24,
  monument_pad: 1 << 25,
  foliage_cleared: 1 << 26,
  path_clear: 1 << 27,
  loot_zone: 1 << 28,
  npc_zone: 1 << 29,
  safe_zone: 1 << 30,
};
